public class EquipmentCharacters : MonoBehaviour
{
    [SerializeField]
    private EquipmentSlotName typeSlot;

    [SerializeField]
    private GameObject[] initialEquipment;

    [SerializeField]
    private ParentSkinned[] parentEquipment;

    public EquipmentSlotName TypeSlot { get => typeSlot; }

    public void DefiniteEquipment(int[] id)
    {
        OffAllClothes();

        for (int i = 0; i < parentEquipment.Length; i++)
        {
            var child = parentEquipment[i].GetSkinnedID(id[i]);
            child.SetActive(true);
        }
    }

    public void OnClothesInitial()
    {
        OffAllClothes();
        foreach (var item in initialEquipment)
        {
            item.SetActive(true);
        }
    }

    private void OffAllClothes()
    {
        foreach (var piece in parentEquipment)
        {
            var children = piece.GetAllSkinned();

            foreach (var child in children)
            {
                child.SetActive(false);
            }
        }
    }
}

